// "Bold Swirl + Grain" Shader
// Inspired by original code by @mmalex
// Modified drastically for an "o-share" vibe

//------------------------------------------------------------
// パラメータ類
//------------------------------------------------------------
#define moblur   4
#define harmonic 25
#define triangle 1   // comment this out for only square

//------------------------------------------------------------
// ハッシュ関数: ランダム値生成
//------------------------------------------------------------
float randHash(vec2 p) {
    // 2Dから1Dへの疑似乱数
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453123);
}

//------------------------------------------------------------
// ランダムノイズ(グレイン)
//------------------------------------------------------------
vec3 grainEffect(vec3 color, vec2 uv, float strength) {
    // ピクセルをベースにしたノイズを生成 (画面全体にザラザラ)
    float n = randHash(floor(uv * iResolution.xy));
    // ノイズの強さを可変に
    return mix(color, color + (n - 0.5) * 0.2, strength);
}

//------------------------------------------------------------
// ビネット効果
//------------------------------------------------------------
float vignette(vec2 uv, float radius, float softness) {
    // aspectを加味して円形がつぶれないようにする
    float aspect = iResolution.x / iResolution.y;
    float d = length(uv * vec2(aspect, 1.0));
    // 中央付近が明るく、端へ行くほど暗く
    return smoothstep(radius, radius - softness, d);
}

//------------------------------------------------------------
// 円 (元コードを踏襲)
//------------------------------------------------------------
vec3 circle(vec2 uv, float rr, float cc, float ss)
{
    // 回転
    uv *= mat2(cc, ss, -ss, cc);

    // 負値 rr の場合、yを反転していたのをそのまま利用
    if (rr < 0.) uv.y = -uv.y;
    rr = abs(rr);

    // 円の距離場
    float r   = length(uv) - rr;
    float pix = fwidth(r);
    float c   = smoothstep(0., pix, abs(r));

    // 半円用に色分け
    float l = smoothstep(0., pix, abs(uv.x) + step(uv.y, 0.) + step(rr, uv.y));

    return vec3(c, c * l, c * l);
}

//------------------------------------------------------------
// 幾何学模様描画 (元コードをやや改変)
//------------------------------------------------------------
vec3 drawPattern(vec2 uv, float th0)
{
    vec3 col = vec3(1.0);
    vec2 uv0 = uv;

    // 端付近で歪みがかかるアニメーション
    th0 -= max(0., uv0.x - 1.5) * 2.0;
    th0 -= max(0., uv0.y - 1.5) * 2.0;

    #ifndef triangle
        float lerpy = 1.0;
    #else
        // 三角波と矩形波をスムーズにブレンド
        float lerpy = smoothstep(-0.6, 0.2, cos(th0 * 0.1));
    #endif

    // 多数の円(奇数 i)を重ねて描画
    for (int i = 1; i < harmonic; i += 2) {
        float th  = th0 * float(i);
        float fl  = mod(float(i), 4.0) - 2.0;
        float cc  = cos(th) * fl;
        float ss  = sin(th);
        float trir = -fl / float(i * i);
        float sqrr =  1.0 / float(i);

        // 三角波半径 or 正方形半径をブレンド
        float rr = mix(trir, sqrr, lerpy);

        col = min(col, circle(uv, rr, cc, ss));

        // 次の円の位置に影響
        uv.x += rr * ss;
        uv.y -= rr * cc;
    }

    // グリッド風ラインを少し残す
    float pix = fwidth(uv0.x);
    if (uv.y > 0. && fract(uv0.y * 10.) < 0.5) {
        col.yz = min(col.yz, smoothstep(0., pix, abs(uv.x)));
    }
    if (uv.x > 0. && fract(uv0.x * 10.) < 0.5) {
        col.yz = min(col.yz, smoothstep(0., pix, abs(uv.y)));
    }

    // 右端・上端に白ライン
    if (uv0.x >= 1.5) col.xy = vec2(smoothstep(0., fwidth(uv.y), abs(uv.y)));
    if (uv0.y >= 1.5) col.xy = vec2(smoothstep(0., fwidth(uv.x), abs(uv.x)));

    return col;
}

//------------------------------------------------------------
// スワール(渦巻き)変形
//------------------------------------------------------------
void swirl(inout vec2 uv, float angle)
{
    float r = length(uv);
    float a = atan(uv.y, uv.x) + angle * r * r;
    uv = r * vec2(cos(a), sin(a));
}

//------------------------------------------------------------
// 背景の大胆なグラデーション (時間 + y座標で色変化)
//------------------------------------------------------------

vec3 boldGradient(vec2 uv, float time)
{
    // グラデーションを白と黒のみに
    // 下 -> 上で白から黒、または黒から白に切り替わるシンプルな設計
    float gray = smoothstep(0.0, 1.0, uv.y * 0.5 + 0.5); // Y座標で白から黒へ
    return vec3(gray); // 白黒のみを返す
}

//------------------------------------------------------------
// メイン
//------------------------------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // UV座標設定
    vec2 uv = fragCoord.xy / iResolution.xy;
    // 画面全体で1.0->0.0となるようYを反転
    uv.y = 1.0 - uv.y;

    // 背景用のUVは別で保持 (グラデーション計算用)
    vec2 uvBg = uv;

    // 見た目のスケールとオフセットは元コードを踏襲
    uv *= 5.0 * (iResolution.x / iResolution.y);
    uv -= 1.5;

    // スワール(渦巻)を追加してみる
    swirl(uv, 0.35);

    // 時間パラメータ
    float time = iTime * 2.0;
    float dt   = 2.0 / 60.0 / float(moblur);

    // 背景色 (大胆グラデーション)
    vec3 bgColor = boldGradient(uvBg, iTime);

    // 幾何学模様生成 (モーションブラー)
    vec3 shapeCol = vec3(0.0);
    float th0 = time;

    for (int mb = 0; mb < moblur; ++mb) {
        shapeCol += drawPattern(uv, th0);
        th0 += dt;
    }
    shapeCol /= float(moblur);

    // ガンマ補正
    shapeCol = pow(shapeCol, vec3(1.0 / 2.2));

    // 背景と幾何学模様をブレンド
    // 図形側のコントラストを強めに
    vec3 col = mix(bgColor, shapeCol, 0.65);

    // グレイン(ノイズ)エフェクト (強さはお好みで)
    col = grainEffect(col, fragCoord.xy / iResolution.xy, 0.15);

    fragColor = vec4(col, 1.0);
}
